// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(this));
        amount = bound(amount, 1, 1 ether);

        vm.deal(attacker, 1 ether);

        vm.deal(address(this), amount);
        (bool sent,) = address(c).call{value: amount}(" ");
        require(sent, "funding failed");

        vm.prank(attacker);
        bool ok;
        try c.sendMoney(attacker, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(address(c).balance == amount);
    }
}
